mapper.select:
select d.id, d.item_id, COALESCE(d.item_name, w.name) as item_name, COALESCE(d.item_thumbnail, w.thumbnail, w.url) as item_thumbnail, COALESCE(w.url, w.thumbnail) as item_url, d.download_type, d.create_by, d.create_time, COALESCE(u.nick_name, CASE WHEN d.create_by LIKE 'fake_like_%' THEN CONCAT('虚拟用户', SUBSTRING(d.create_by, 11)) WHEN d.create_by IS NULL OR d.create_by = '' THEN '游客' ELSE d.create_by END) as create_by_name from px_wallpaper_download_record d left join px_wallpaper w on d.item_id = w.id left join sys_user u on d.create_by = u.user_id
d.create_by = #{createBy}
order by d.create_time desc

SELECT DATE_FORMAT(d.create_time, '%Y-%m-%d') AS date, COUNT(*) AS count FROM px_wallpaper_download_record d WHERE d.create_time IS NOT NULL
AND d.create_time >= #{beginTime}
AND d.create_time <= #{endTime}
GROUP BY DATE_FORMAT(d.create_time, '%Y-%m-%d') ORDER BY date

SELECT t.userId AS userId, COALESCE(MAX(u.nick_name), CASE WHEN t.userId LIKE 'fake_like_%' THEN CONCAT('虚拟用户', SUBSTRING(t.userId, 11)) WHEN t.userId IS NULL OR t.userId = '' THEN '游客' ELSE t.userId END) AS nickName, SUM(t.cnt) AS count, MAX(t.create_time) AS lastDownloadTime FROM ( SELECT create_by AS userId, COUNT(*) AS cnt, MAX(create_time) AS create_time FROM px_wallpaper_download_record WHERE create_time IS NOT NULL
AND create_time >= #{beginTime}
AND create_time <= #{endTime}
GROUP BY create_by ) t LEFT JOIN sys_user u ON t.userId = u.user_id GROUP BY t.userId

SELECT d.create_by AS userId, COALESCE(u.nick_name, CASE WHEN d.create_by LIKE 'fake_like_%' THEN CONCAT('虚拟用户', SUBSTRING(d.create_by, 11)) WHEN d.create_by IS NULL OR d.create_by = '' THEN '游客' ELSE d.create_by END) AS nickName, DATE_FORMAT(d.create_time, '%Y-%m-%d') AS date, COUNT(*) AS count FROM px_wallpaper_download_record d LEFT JOIN sys_user u ON d.create_by = u.user_id WHERE d.create_time IS NOT NULL
AND d.create_time >= #{beginTime}
AND d.create_time <= #{endTime}
GROUP BY d.create_by, DATE_FORMAT(d.create_time, '%Y-%m-%d')
